package com.wifiguard.enterprise;

import java.util.Arrays; import java.util.HashSet; import java.util.Locale; import java.util.Set;
public final class LabSimulator {
    private LabSimulator(){}
    private static final Set<String> COMMON=new HashSet<>(Arrays.asList("12345678","123456789","password","senha1234","admin1234","qwerty123","internet","wifi12345","empresa123","abcd1234","11111111","00000000","12341234","87654321","iloveyou"));
    public static String run(String trainingSecret){String s=trainingSecret==null?"":trainingSecret.trim();boolean common=COMMON.contains(s.toLowerCase(Locale.US));int classes=0;if(s.matches(".*[a-z].*"))classes++;if(s.matches(".*[A-Z].*"))classes++;if(s.matches(".*[0-9].*"))classes++;if(s.matches(".*[^A-Za-z0-9].*"))classes++;String strength;if(s.length()<10||common)strength="FRACA";else if(s.length()<14||classes<3)strength="MODERADA";else if(s.length()>=16&&classes>=3)strength="FORTE";else strength="BOA";StringBuilder b=new StringBuilder();b.append("LABORATÓRIO SEGURO — nenhum pacote é transmitido\n\n");b.append("1) Simulação de dicionário WPA/WPA2\n");b.append(common?"Resultado: segredo de treino encontrado na lista de senhas fracas.\n":"Resultado: segredo de treino não apareceu na pequena lista interna.\n");b.append("Classificação do segredo: ").append(strength).append("\n\n");b.append("2) WPS\nSimulação: demonstra risco de PIN e recomenda WPS desativado. Não envia PINs ao roteador.\n\n");b.append("3) WEP\nSimulação: marca WEP como crítico e obsoleto. Não coleta IVs nem recupera chaves.\n\n");b.append("4) Deautenticação\nSimulação: demonstra perda de associação e necessidade de PMF/802.11w. Nenhum frame de deauth é transmitido.\n\n");b.append("5) Handshake\nUse 'Analisar PCAP' para verificar EAPOL e as mensagens M1–M4 em uma captura de laboratório já existente.");return b.toString();}
}
